examples.template:
Box {
    MonarchButton(text = {{label}}, onClick = { open = true }, variant = MonarchButtonVariant.Secondary)
    MonarchPopover(expanded = open, onDismissRequest = { open = false }, label = "Share") {
        MonarchText(text = "Link", style = MonarchTextStyle.Label)
        Row(
            horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            MonarchTextField(
                value = {{url}},
                onValueChange = {},
                readOnly = true,
                modifier = Modifier.weight(1f),
            )
            MonarchButton(
                text = "Copy link",
                onClick = { /* Copy the link to the clipboard. */ },
                variant = MonarchButtonVariant.Secondary,
                size = MonarchButtonSize.Sm,
                leadingIcon = { MonarchIcon(SampleIcons.Copy, contentDescription = null, size = MonarchIconSize.Sm) },
            )
        }
        MonarchDivider()
        MonarchButton(
            text = "Email",
            onClick = { /* Open a new message with the link. */ },
            variant = MonarchButtonVariant.Ghost,
            size = MonarchButtonSize.Sm,
        )
    }
}

